{
  "headline": "Amlodipine besylate is not on FDA's shortage list; our supply traces to a plant with multiple OAI inspections and warning letters",
  "headline_cites": ["D3", "E7", "E8", "E12", "E14", "E16", "E17", "E18"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include amlodipine besylate as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Our current label for the product names Zydus Lifesciences Limited (FEI 3002984011) as the manufacturing plant.",
      "cites": ["E19"]
    },
    {
      "text": "That plant received OAI classifications in 2011, 2014, and 2019, with corresponding warning letters in 2011, 2015, and 2019.",
      "cites": ["E8", "E12", "E14", "E16", "E17", "E18"]
    },
    {
      "text": "The most recent inspection of that plant was VAI in 2022.",
      "cites": ["E15"]
    },
    {
      "text": "A second Zydus plant (FEI 3005430968) also appears on the label and received a warning letter on 2026-06-02.",
      "cites": ["E7", "E6"]
    },
    {
      "text": "Corvale East has 14.2 days on hand and Corvale General has 24.4 days on hand for the 5 mg tablet.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "The rule-based alternate manufacturer ranked first is Ajanta Pharma USA Inc., which is not on FDA's shortage list today.",
      "cites": ["D4"]
    }
  ]
}
